receipt=dict(verdict='PARTIAL' if after['errors'] else 'PASS',reason='Main SDK and Godot environment migrated and validated; inaccessible scratch remnants retained and shared external toolchains left at existing locations.',before_accessible_bytes=before['accessible_bytes'],after_accessible_bytes=after['accessible_bytes'],net_reduction_bytes=before['accessible_bytes']-after['accessible_bytes'],percent_reduction=100*(before['accessible_bytes']-after['accessible_bytes'])/before['accessible_bytes'],bytes_migrated=sum(r['bytes'] for r in manifest),original_file_bytes_removed=missing_originals,destinations=destinations,updated_source_configuration_files=len(set(paths)),updated_paths=sorted(set(paths)),remaining_tools=[(p,n) for p,n in after['directories'].items() if p.startswith('.tools/') and p.count('/')==1],inaccessible_paths=after['errors'],inaccessible_bytes=None,pre_removal_validation=validation,post_removal_validation=post,regressions=reg,pinned_binaries=pins,all_seven_pins_unchanged=len(pins)==7 and all(v['expected']==v['actual'] for v in pins.values()),sdk_build_verified=True,physical_disk_savings_claimed=0,physical_storage_note='Relocation reduces repository footprint. C: source and D: destination are different volumes; no whole-machine free-space saving is claimed. Previously compressed files may occupy more space at the destination.',recovery='Use manifest source/destination mapping. To restore, copy destination files back without overwriting user files, verify critical hashes, and set UNICORE_OCCT_SDK_ROOT / UNICORE_GODOT_ENV_ROOT to restored paths. Original worker/build manifest are retained under SDK/OCCT/migration-original-build.',limitations=['Inaccessible scratch directories remain; their sizes are unknown. Report totals cover accessible regular files only.','Existing shared D:/msys64 and C:/Qt toolchains remain in place; external SDK build still requires them.','SDK package archives remain with their locked SDK-local names for offline reconstruction.','Project .godot cache remains local because Godot imports use the project directory; editor scan verified it.','Other historical HPC benchmark directories remain in .tools; historical reports and receipts are preserved.','Legacy SCons build still uses its established local intermediate paths; active Godot472 builder uses external cache.'])
